@classmethod
def make_compound_path(cls, *args):
    """Make a compound path from a list of Path objects."""
    # Handle an empty list in args (i.e. no args).
    if not args:
        return Path(np.empty([0, 2], dtype=np.float32))

    vertices = []
    codes = []
    i = 0

    for path in args:
        if not isinstance(path, cls):
            raise ValueError("Each argument must be a Path object.")

        path_length = len(path.vertices)
        if path_length == 0:
            continue  # Skip empty paths

        vertices.append(path.vertices)

        if path.codes is None:
            if i == 0:
                codes.append(np.full((1,), cls.MOVETO, dtype=cls.code_type))  # Start with MOVETO for the first segment
            codes.append(np.full((path_length - 1,), cls.LINETO, dtype=cls.code_type))  # LINETO for the rest
        else:
            codes.append(path.codes)

        i += path_length

    # Concatenate all vertices and codes
    vertices = np.concatenate(vertices)
    codes = np.concatenate(codes)

    # Remove internal STOP codes if present
    stop_indices = np.where(codes == cls.STOP)[0]
    if len(stop_indices) > 0:
        codes = np.delete(codes, stop_indices[1:])  # Keep only the first STOP

    return cls(vertices, codes)
