@classmethod
def make_compound_path(cls, *args):
    """Make a compound path from a list of Path objects."""
    # Handle an empty list in args (i.e. no args).
    if not args:
        return Path(np.empty([0, 2], dtype=np.float32))

    vertices_list = []
    codes_list = []

    for path in args:
        if path.codes is None:
            # If path has no codes, treat all vertices as LINETO except the first MOVETO
            vertices_list.append(path.vertices)
            if len(path.vertices) > 0:
                codes_list.append([cls.MOVETO] + [cls.LINETO] * (len(path.vertices) - 1))
        else:
            # If path has codes, use them directly
            vertices_list.append(path.vertices)
            codes_list.append(path.codes)

    vertices = np.concatenate(vertices_list)
    codes = np.concatenate(codes_list)

    # Remove internal STOP codes if they exist
    stop_indices = np.where(codes == cls.STOP)[0]

    if len(stop_indices) > 0:
        # If there are STOP codes, keep only the first one
        codes = np.delete(codes, stop_indices[1:])

    return cls(vertices, codes)
