@classmethod
def make_compound_path(cls, *args):
    """Make a compound path from a list of Path objects."""
    # Handle an empty list in args (i.e., no args).
    if not args:
        return Path(np.empty([0, 2], dtype=np.float32))

    vertices = []
    codes = []

    for path in args:
        if not isinstance(path, cls):
            raise ValueError("Each argument must be a Path object.")

        if path.codes is None:
            # Handle case where path.codes is None
            codes.append([cls.MOVETO] + [cls.LINETO] * (len(path.vertices) - 1))
        else:
            codes.append(path.codes)

        vertices.append(path.vertices)

    # Concatenate the lists to form final vertices and codes arrays
    vertices = np.concatenate(vertices)

    # Flatten the list of codes; they might be lists of arrays
    codes = np.concatenate(codes)

    # Remove internal STOP codes while keeping only one STOP at the end
    stop_indices = np.where(codes == cls.STOP)[0]
    if len(stop_indices) > 1:
        first_stop_index = stop_indices[0]
        codes = np.delete(codes, stop_indices[1:])  # Remove all but the first STOP
        # To ensure that we leave only one stop at the end
        codes = np.concatenate([codes[:first_stop_index], [cls.STOP], codes[first_stop_index:]])

    return cls(vertices, codes)
