@classmethod
def make_compound_path(cls, *args):
    """Make a compound path from a list of Path objects."""
    # Handle an empty list in args (i.e. no args).
    if not args:
        return Path(np.empty([0, 2], dtype=np.float32))

    vertices = []
    codes = []

    for path in args:
        if path.codes is None:
            vertices.append(path.vertices)
            codes.append(np.full(len(path.vertices), cls.LINETO, dtype=cls.code_type))
            codes[0][0] = cls.MOVETO  # Set first MOVETO code explicitly
        else:
            # If there are STOP codes, we need to adjust them.
            vertices.append(path.vertices)
            codes.append(path.codes)

    # Concatenate all vertices and codes
    vertices = np.concatenate(vertices)
    codes = np.concatenate(codes)

    # Ensure there are no internal STOP codes. 
    if np.any(codes == cls.STOP):
        stop_indices = np.where(codes == cls.STOP)[0]
        # Only keep the first stop code for the whole compound path
        codes = np.delete(codes, stop_indices[1:])

    return cls(vertices, codes)
