@classmethod
def make_compound_path(cls, *args):
    """Make a compound path from a list of Path objects."""
    if not args:
        return Path(np.empty([0, 2], dtype=np.float32))

    vertices = []
    codes = []

    for path in args:
        if isinstance(path, cls):
            if path.codes is None:
                codes.append(np.full(len(path.vertices), cls.LINETO, dtype=cls.code_type))
                codes[0][0] = cls.MOVETO  # First vertex should be MOVETO
            else:
                codes.append(path.codes)
            vertices.append(path.vertices)
        else:
            raise ValueError("All arguments must be Path objects.")

    # Concatenate vertices and codes
    vertices = np.concatenate(vertices)
    codes = np.concatenate(codes)

    # Remove internal STOP codes (if any) and ensure only one STOP at the end
    stop_count = np.sum(codes == cls.STOP)
    if stop_count > 1:
        codes = codes[codes != cls.STOP]
        codes = np.append(codes, cls.STOP)

    return cls(vertices, codes)
