@classmethod
def make_compound_path(cls, *args):
    """Make a compound path from a list of Path objects."""
    # Handle an empty list in args (i.e. no args).
    if not args:
        return Path(np.empty([0, 2], dtype=np.float32))

    vertices = []
    codes = []

    for path in args:
        if not isinstance(path, cls):
            raise ValueError("All arguments must be instances of Path")

        # Get the vertices and append them
        vertices.append(path.vertices)

        # Get the corresponding codes
        if path.codes is None:
            # If there are no codes, all elements are LINETO except the first MOVETO
            codes.append(np.full(len(path.vertices), cls.LINETO))
            codes[-len(path.vertices)] = cls.MOVETO   # Set MOVETO for the first code
        else:
            codes.append(path.codes)

    # Concatenate all vertices and codes
    vertices = np.concatenate(vertices)
    codes = np.concatenate(codes)

    # Replace internal STOPs with LINETOs to maintain pathological conditions
    cleaned_codes = []
    for code in codes:
        if code == cls.STOP:
            cleaned_codes.append(cls.LINETO)
        else:
            cleaned_codes.append(code)

    return cls(vertices, np.array(cleaned_codes, dtype=cls.code_type))
```

